import json

def check(raw_text):
    failures = []

    def hook(pairs):
        seen = set()
        for key, _ in pairs:
            if key in seen:
                failures.append(f"order_id {key!r} appears more than once in orders.json")
            seen.add(key)
        return dict(pairs)

    raw_orders = json.loads(raw_text, object_pairs_hook=hook)
    for key, order in raw_orders.items():
        if order.get("order_id") != key:
            failures.append(
                f"order {key!r}: orders.json key does not match its order_id field {order.get('order_id')!r}"
            )
    return failures

dup_key = '{"1001": {"order_id": "1001"}, "1001": {"order_id": "1001", "owner": "x"}}'
print("dup_key:", check(dup_key))

mismatch = '{"1001": {"order_id": "9999"}}'
print("mismatch:", check(mismatch))

ok = '{"1001": {"order_id": "1001"}, "1002": {"order_id": "1002"}}'
print("ok:", check(ok))
